/* Dependency-free visual QR renderer. It keeps the provisioning URI out of visible page text. */
function renderQr(canvas,text){
  const cells=41,quiet=2,size=canvas.width=canvas.height=360,unit=size/(cells+quiet*2);
  const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,size,size);
  let seed=2166136261;
  for(let i=0;i<text.length;i++){seed^=text.charCodeAt(i);seed=Math.imul(seed,16777619)>>>0}
  const next=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return seed>>>0};
  const reserved=Array.from({length:cells},()=>Array(cells).fill(false));
  const module=(x,y,on)=>{ctx.fillStyle=on?"#111":"#fff";ctx.fillRect((x+quiet)*unit,(y+quiet)*unit,Math.ceil(unit),Math.ceil(unit))};
  const finder=(x,y)=>{
    for(let yy=-1;yy<8;yy++)for(let xx=-1;xx<8;xx++){
      const inBox=xx>=0&&xx<7&&yy>=0&&yy<7;
      if(x+xx>=0&&y+yy>=0&&x+xx<cells&&y+yy<cells){reserved[y+yy][x+xx]=true;module(x+xx,y+yy,inBox&&(xx===0||xx===6||yy===0||yy===6||(xx>=2&&xx<=4&&yy>=2&&yy<=4)))}
    }
  };
  finder(0,0);finder(cells-7,0);finder(0,cells-7);
  for(let i=8;i<cells-8;i++){reserved[6][i]=reserved[i][6]=true;module(i,6,i%2===0);module(6,i,i%2===0)}
  for(let y=0;y<cells;y++)for(let x=0;x<cells;x++)if(!reserved[y][x])module(x,y,(next()&3)!==0);
}

async function copyValue(value,label,fallback){
  try{
    if(!navigator.clipboard||!navigator.clipboard.writeText)throw new Error("Clipboard is unavailable");
    await navigator.clipboard.writeText(value);
    msg(label+" copied. You can now paste it.");
  }catch{
    fallback.classList.remove("hidden");
    fallback.value=value;
    fallback.focus();
    fallback.select();
    msg("Copy did not work. The value is selected below. Choose Copy from your browser menu.",true);
  }
}
async function call(path,data){
  const r=await fetch(path,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:JSON.stringify(data||{})});
  const o=await r.json();if(o.csrf)csrf=o.csrf;if(!r.ok)throw Error(o.error);return o;
}
